mapper.select:
SELECT 
FROM mt_promotion_ad_daily
WHERE shop_id = #{shopId}
  AND biz_date = #{bizDate}
  AND channel = #{channel}
LIMIT 1

SELECT
    COALESCE(SUM(show_count), 0) AS show_count,
    COALESCE(SUM(click_count), 0) AS click_count,
    COALESCE(SUM(debit_cents), 0) AS debit_cents
FROM mt_promotion_ad_daily
WHERE shop_id = #{shopId}
  AND biz_date BETWEEN #{startBizDate} AND #{endBizDate}
  AND channel = #{channel}
